import os, json, collections

json_file = "/home/USER/runs/paper/qwen-in-glm-hpl-u1-letter/frozen/seen-4/play/users/u034/system/state/workspace/programs/task-0f6e5a2f.json"
with open(json_file) as f:
    demos = json.load(f)

print("Let's look at the 2x2 pattern completion idea:\n")

for i, demo in enumerate(demos):
    inp = demo['input']
    out = demo['output']
    H, W = len(inp), len(inp[0])

    # Find all changes
    changes = []
    for y in range(H):
        for x in range(W):
            if inp[y][x] != out[y][x]:
                changes.append((y, x))

    if not changes:
        continue

    # Find all 2x2 blocks
    all_2x2_blocks = []
    for y in range(H-1):
        for x in range(W-1):
            if inp[y][x] == inp[y+1][x] == inp[y][x+1] == inp[y+1][x+1]:
                all_2x2_blocks.append((y, x, inp[y][x]))

    # Find 2x2 blocks that "break" when looking at a changed cell
    # For example, a cell (y,x) is part of a "potential" 2x2 if 3 of the 4 positions have same color
    # but cell (y,x) has a different color

    for y, x in sorted(changes):
        old = inp[y][x]
        new = out[y][x]

        # Check which 2x2 blocks this cell is part of in the input
        current_2x2_in_cell = []
        for y_2x2, x_2x2, c in all_2x2_blocks:
            if y_2x2 <= y <= y_2x2+1 and x_2x2 <= x <= x_2x2+1:
                current_2x2_in_cell.append((y_2x2, x_2x2, c))

        # Check potential 2x2 blocks if we change old to new
        # A potential 2x2 at (y-1, x-1) needs inp[y-1][x-1] == inp[y-1][x] == inp[y][x+1] == inp[y][x]
        # etc.
        potential_2x2 = []
        for y_2x2, x_2x2, c in all_2x2_blocks:
            # Does the 2x2 block share a row or col with this cell?
            if y_2x2 == y-1 and x_2x2 == x-1:
                # Check if inp[y-1][x-1] == inp[y-1][x] == inp[y][x+1] == inp[y][x]
                if inp[y-1][x-1] == inp[y-1][x] == inp[y][x+1] and inp[y-1][x-1] == inp[y][x]:
                    potential_2x2.append((y_2x2, x_2x2, c, 'BR'))
            if y_2x2 == y-1 and x_2x2 == x:
                if inp[y-1][x-1] == inp[y-1][x+1] == inp[y][x-1] == inp[y][x]:
                    potential_2x2.append((y_2x2, x_2x2, c, 'BL'))
            # etc

        print(f"Demo {i+1}, Cell ({y},{x}): {old}->{new}")
        print(f"  Current 2x2 in cell: {len(current_2x2_in_cell)}")
        for c in current_2x2_in_cell:
            print(f"    {c}")

        # What about "opposite direction"? The 2x2 is COMPLETABLE by having 3 cells opposite the cell?
        # For (y,x), look at (y+1, x+1), (y+1, x), (y, x+1) - if they're all same, we could complete
        opp_y, opp_x = y+1, x+1
        if opp_y < H and opp_x < W:
            if inp[opp_y][x] == inp[y][opp_x] == inp[opp_y][opp_x] and inp[opp_y][opp_x] == old:
                print(f"  Opposite 2x2 (BR direction): {inp[opp_y][x]} would complete")

        print()

