import json, collections

def transform(grid):
    g=[r[:] for r in grid]
    H,W=len(g),len(g[0])

    cnt = collections.Counter(x for r in g for x in r)
    bg = cnt.most_common(1)[0][0]

    line = None
    vert = None

    # Find vertical line of 2s
    for c in range(W):
        if all(g[r][c] == 2 for r in range(H)):
            line, vert = c, True

    # Find horizontal line of 2s
    if not vert:
        for r in range(H):
            if all(g[r][c] == 2 for c in range(W)):
                line, vert = r, False

    sc = [k for k in cnt if k not in (bg, 2)][0]
    cells = [(r, c) for r in range(H) for c in range(W) if g[r][c] == sc]

    # Move original cells to background
    if vert:
        if min(c for r,c in cells) > line:
            gap = min(c for r,c in cells) - line - 1
            dr, dc = 0, -gap
        else:
            gap = line - max(c for r,c in cells) - 1
            dr, dc = 0, gap
    else:
        if min(r for r,c in cells) > line:
            gap = min(r for r,c in cells) - line - 1
            dr, dc = -gap, 0
        else:
            gap = line - max(r for r,c in cells) - 1
            dr, dc = gap, 0

    for r, c in cells:
        g[r][c] = bg

    # Place colored cell at shifted position
    for r, c in cells:
        g[r+dr][c+dc] = sc

    # Draw new line with 8s
    cells_shifted = [(r+dr, c+dc) for r, c in cells]
    if vert:
        mc = (max(c for r,c in cells)+1) if min(c for r,c in cells) > line else (min(c for r,c in cells)-1)
        for r in range(H):
            if 0 <= r < H:
                g[r][mc] = 8  # Add bounds check
    else:
        mr = (min(r for r,c in cells)-1) if max(r for r,c in cells) < line else (max(r for r,c in cells)+1)
        for c in range(W):
            if 0 <= c < W:
                g[mr][c] = 8

    return g

